INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass alle Piktogramme für Sicherheit immer sprachunabhängig sind?', 2, '[{"text": "Ja", "correct": true, "because": "Entwickelt für universelle Verständlichkeit"}, {"text": "Nein", "correct": false, "because": "Selbsterklärend durch Symbole"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Norm regelt die Gestaltung solcher Zeichen in Europa?', 3, '[{"text": "DIN EN ISO 7010", "correct": true, "because": "International abgestimmte Symbole"}, {"text": "DIN 4844-1", "correct": false, "because": "Nationale Ergänzung"}, {"text": "ANSI Z535", "correct": false, "because": "US-Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kategorien gehören zu diesen Zeichen?', 5, '[{"text": "Verbotszeichen", "correct": true, "because": "Untersagen Verhalten"}, {"text": "Gebotszeichen", "correct": true, "because": "Vorschreiben Handlungen"}, {"text": "Warnzeichen", "correct": true, "because": "Hinweisen auf Gefahren"}, {"text": "Farbcodes", "correct": false, "because": "Keine Kategorie"}, {"text": "Logos", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rettungszeichen sind grün. b) Sie zeigen immer Gefahren an.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, zeigen Rettungswege"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Anbringung solcher Zeichen?', 4, '[{"text": "Erkennungsweite", "correct": false, "because": "Sichert Sichtbarkeit"}, {"text": "Normen", "correct": false, "because": "Bestimmen Gestaltung"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Warnzeichen immer gelb sind?', 2, '[{"text": "Ja", "correct": true, "because": "Gelb mit schwarzem Dreieck"}, {"text": "Nein", "correct": false, "because": "Norm definiert Gelb"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Farbe haben Gebotszeichen nach DIN EN ISO 7010?', 4, '[{"text": "Blau", "correct": true, "because": "Rundes blaues Schild"}, {"text": "Rot", "correct": false, "because": "Für Verbotszeichen"}, {"text": "Grün", "correct": false, "because": "Für Rettungszeichen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass alle Zeichen in Augenhöhe angebracht werden müssen. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Sichtbarkeit"}, {"text": "Ja", "correct": false, "because": "Ort variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Brandschutzzeichen quadratisch?', 2, '[{"text": "Ja", "correct": true, "because": "Rot und quadratisch"}, {"text": "Nein", "correct": false, "because": "Norm definiert Form"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zeichen zeigen Fluchtwege an?', 5, '[{"text": "Rettungszeichen", "correct": true, "because": "Kennzeichnen Notausgänge"}, {"text": "Brandschutzzeichen", "correct": false, "because": "Für Löschmittel"}, {"text": "Warnzeichen", "correct": false, "because": "Für Gefahren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Platzierung solcher Zeichen?', 4, '[{"text": "Sichtbarkeit", "correct": true, "because": "Sichert Wahrnehmung"}, {"text": "Schnelle Anbringung", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Dekoratives Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verbotszeichen sind rot. b) Sie sind immer quadratisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, rund mit Schrägbalken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Auswahl solcher Zeichen?', 3, '[{"text": "Normen", "correct": false, "because": "Definieren Gestaltung"}, {"text": "Erkennungsweite", "correct": false, "because": "Sichert Sichtbarkeit"}, {"text": "Schriftart", "correct": true, "because": "Piktogramme ohne Text"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Erkennungsweite eines Zeichens prüfe?', 4, '[{"text": "Abstand messen, bis Symbol erkennbar", "correct": true, "because": "Bestimmt Größe"}, {"text": "Nur Farbe prüfen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Messung", "correct": false, "because": "Unpräzise"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass langnachleuchtende Zeichen immer nötig sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Nur bei fehlender Beleuchtung"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Zeichen zeigt eine Gefahr durch Strom an?', 4, '[{"text": "Warnzeichen mit Blitzsymbol", "correct": true, "because": "Gelb mit schwarzem Blitz"}, {"text": "Gebotszeichen", "correct": false, "because": "Für Verhalten"}, {"text": "Verbotszeichen", "correct": false, "because": "Untersagt Handlungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die ASR A1.3 in Deutschland bindend?', 2, '[{"text": "Ja", "correct": true, "because": "Regelt Kennzeichnung"}, {"text": "Nein", "correct": false, "because": "Teil der Arbeitsstättenverordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zeichen sind für Brandschutz relevant?', 5, '[{"text": "Brandschutzzeichen", "correct": true, "because": "Zeigen Löschmittel"}, {"text": "Rettungszeichen", "correct": false, "because": "Für Fluchtwege"}, {"text": "Warnzeichen", "correct": false, "because": "Für Gefahren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Anbringung solcher Zeichen unwichtig?', 3, '[{"text": "Normenkonformität", "correct": false, "because": "Sichert Verständlichkeit"}, {"text": "Sichtbarkeit", "correct": false, "because": "Gewährleistet Wirkung"}, {"text": "Dekoratives Aussehen", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich einen Arbeitsplatz kennzeichne?', 4, '[{"text": "Gefährdung beurteilen, normgerechte Zeichen wählen", "correct": true, "because": "Sichert Schutz"}, {"text": "Zufällige Zeichen wählen", "correct": false, "because": "Riskiert Missverständnisse"}, {"text": "Ohne Normen", "correct": false, "because": "Verstößt gegen Vorschriften"}]');
